  const context = Number.parseInt(parsedUrl.searchParams.get("context") ?? "2", 10);

  if (realWorkspaceRoot === null) {
    const body = JSON.stringify({ available: false, reason: "WORKSPACE_ROOT_UNAVAILABLE" });
